import { useState } from "react";

import { SectionPage, Specimen } from "../kit.js";

import { IconEndpoint, IconRefresh, IconRemoteControl, IconTaskManager, IconTerminal } from "../../icons/generated/icons.js";

import { EntityHeader } from "../../shell/index.js";

import { Button } from "../../ui/button/index.js";

